const LEVEL_BADGES: Record<NodeLogLevel, string> = {
  DEBUG: `${ANSI.bgGray} DEBUG ${ANSI.reset}`,
  INFO: `${ANSI.bgBlue}  INFO ${ANSI.reset}`,
  ACTION: `${ANSI.bgMagenta} ACTION${ANSI.reset}`,
